        "interesado",
        "cotizado",
        "link_enviado",
        "handoff"
      ]
    },
    "handoff_motivo": {
      "type": "string"
    },
    "resumen": {
      "type": "string"
    }
  },
  "required": [
    "mensajes",
    "productos_a_mostrar",
    "fotos_extra_de",
    "etapa",
    "handoff_motivo",
    "resumen"
  ]
}

